n=21
g=[[0]*n for _ in range(n)]
pts={3:[(0,14),(3,17),(5,9),(6,10),(6,13),(8,15),(8,17)],6:[(2,3),(17,3)],7:[(2,6)],1:[(2,7),(17,7)],4:[(3,2)],8:[(13,10),(15,16),(17,13)]}
for col,ps in pts.items():
 for r,c in ps:g[r][c]=col
# direct aligned segments between same-color points, horizontal/vertical/45-degree
import itertools
for col,ps in pts.items():
 for (r1,c1),(r2,c2) in itertools.combinations(ps,2):
  dr,dc=r2-r1,c2-c1
  if dr==0 or dc==0 or abs(dr)==abs(dc):
   sr=(dr>0)-(dr<0); sc=(dc>0)-(dc<0)
   for k in range(max(abs(dr),abs(dc))+1):
    r,c=r1+k*sr,c1+k*sc
    # don't overwrite any distinct original input color
    if g[r][c]==0 or g[r][c]==col:g[r][c]=col
# inferred copied bars: 6 -> 4 offset (+1,-1); 1 -> 7 offset (0,-1)
for r in range(2,18):
 if 0<=r+1<n: # source six line translated (1,-1) rows3..18
  if g[r+1][2]==0:g[r+1][2]=4
for r in range(2,18):
 if g[r][6]==0:g[r][6]=7
print('\n'.join(' '.join(map(str,row)) for row in g))
print('nonzero rows:', [ [(i,v) for i,v in enumerate(row) if v] for row in g])
